 arrow:'M5 12h14m-5-5 5 5-5 5', leaf:'M20 4C7 2 2 9 7 16c6 5 13-1 13-12ZM4 21 16 9',
 mail:'M3 5h18v14H3V5Zm0 0 9 8 9-8', book:'M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-1-7-2-10 1Zm0 0v15',
 sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',
