 play:'m8 4 12 8-12 8V4Z', check:'m4 12 5 5L20 6', close:'m6 6 12 12M18 6 6 18',
 hint:'M8 16c0-3-3-3-3-7a7 7 0 0 1 14 0c0 4-3 4-3 7H8Zm1 4h6',
